function initWPMap(){var e=new google.maps.LatLng(HOUSE.lat,HOUSE["long"]),o={zoom:14,center:e,mapTypeId:google.maps.MapTypeId.ROADMAP,disableDefaultUI:!0,animation:google.maps.Animation.DROP,scrollwheel:!1},n=new google.maps.Map(document.getElementById("map"),o),a=HOUSE.office+",<br />"+HOUSE.street+"<br />"+HOUSE.city,t=new google.maps.InfoWindow({content:a,maxWidth:500}),i=new google.maps.Marker({position:e,map:n,icon:HOUSE.images+"map/marker.png"});google.maps.event.addListener(i,"click",function(){t.open(n,i),n.setZoom(16)}),markers.push(i),google.maps.event.addDomListener(window,"resize",function(){var e=n.getCenter();google.maps.event.trigger(n,"resize"),n.setCenter(e)})}function myClick(e){google.maps.event.trigger(markers[e],"click")}var markers=[];$(document).ready(function(){var e=$("#map");e.length&&initWPMap()});